            ipAddrAry[3] = pSlSockEvent->EventData.ipLeased.ip_address & 0xFF;
            WiFiClass::_registerNewDeviceIP(ipAddrAry, pSlSockEvent->EventData.ipLeased.mac);
            WiFiClass::_connectedDeviceCount++;
            break;

